import random
from datetime import datetime, timedelta
from typing import List, Dict
import uuid

class MockExternalClient:
    """
    Mock implementation of an ITSM API client for POC purposes.
    Generates random data to simulate an external system.
    """

    def fetch_modified_since(
        self,
        entity_type: str,
        modified_since: datetime,
        batch_size: int = 100
    ) -> List[Dict]:
        """
        Simulate fetching records modified since a given timestamp.
        For the POC, we'll generate a few random records each time if the 
        time window is small (indicating a recent sync), or many if large.
        """
        now = datetime.utcnow()
        # If modified_since is very old (first sync), return more records
        if (now - modified_since).days > 1:
            count = 50
        else:
            # Randomly return 0-5 records to simulate activity
            count = random.randint(0, 5)

        records = []
        for _ in range(count):
            records.append(self._generate_record(entity_type))
            
        return records

    def fetch_all_active_ids(self, entity_type: str) -> List[str]:
        """
        Simulate fetching all active IDs. 
        For POC, this might be hard to make consistent without state, 
        so we'll return an empty list or a static list to avoid deleting everything.
        """
        # SAFE POC STRATEGY: Return empty to prevent mass deletion simulation
        # unless we want to test deletion specifically.
        return []

    def _generate_record(self, entity_type: str) -> Dict:
        """Generate a single random record based on entity type."""
        sys_id = str(uuid.uuid4())
        now = datetime.utcnow()
        
        base = {
            "sys_id": sys_id,
            "sys_updated_on": now,
            "number": f"{entity_type.upper()[:3]}{random.randint(10000, 99999)}",
            "short_description": f"Simulated {entity_type} {sys_id[:8]}",
            "description": "Generated by MockExternalClient for POC testing.",
            "state": random.choice(["new", "in_progress", "resolved", "closed"]),
        }

        if entity_type == "incident":
            base.update({
                "priority": random.randint(1, 4),
                "urgency": random.randint(1, 3),
                "impact": random.randint(1, 3),
                "assigned_to": "user_mock",
                "assignment_group": "group_mock",
                "opened_at": now - timedelta(days=random.randint(0, 30)),
                "resolved_at": None,
                "closed_at": None,
            })
        elif entity_type == "change":
            base.update({
                "risk": random.choice(["low", "moderate", "high"]),
                "type": random.choice(["standard", "normal", "emergency"]),
                "requested_by": "user_mock",
                "assigned_to": "group_mock",
                "start_date": now + timedelta(days=2),
                "end_date": now + timedelta(days=3),
                "opened_at": now - timedelta(days=5),
                "closed_at": None,
            })
        elif entity_type == "event":
            base.update({
                "source": random.choice(["Datadog", "Splunk", "Nagios", "CloudWatch"]),
                "severity": random.randint(1, 5),
                "node": random.choice(["db-prod-01", "web-prod-02", "redis-cache-01", "worker-node-05"]),
                "message_key": f"cpu_high_{random.randint(1000, 9999)}",
                "description": f"High CPU utilization on {base.get('node', 'host')}",
                "opened_at": now,
                "closed_at": None,
                "state": random.choice(["open", "acknowledged", "closed"]),
            })
            
        return base
